const CACHE_DAYS = Number(process.env.ANALYTICS_CACHE_DAYS) || 7;
const CACHE_MS = CACHE_DAYS * 24 * 60 * 60 * 1000;

/** True when a stored section was generated by the current schema and is under CACHE_DAYS old. */
const isFresh = (section, schemaVersion) =>
  Boolean(section) &&
  section.schemaVersion === schemaVersion &&
  Date.now() - new Date(section.analyzedAt).getTime() < CACHE_MS;

module.exports = { isFresh };
